int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> depth_stack;
    int current_depth = 0;
    const char* pos = start;

    while (pos < end && item_limit > 0) {
        if (current_depth > depth_limit) {
            ec = error_code::depth_exceeded;
            if (error_pos)
                *error_pos = static_cast<int>(pos - start);
            return 1;
        }

        if (*pos == 'd') {
            // Dictionary
            depth_stack.push(current_depth);
            ++current_depth;
            ++pos;
        }
        else if (*pos == 'l') {
            // List
            depth_stack.push(current_depth);
            ++current_depth;
            ++pos;
        }
        else if (*pos == 'i') {
            // Integer
            ++pos;
            const char* end_int = std::find_if(pos, end, [](char c) { return c == 'e'; });
            if (end_int == end) {
                ec = error_code::unexpected_eof;
                if (error_pos)
                    *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            lazy_entry::lazy_int val;
            try {
                val = std::stoll(std::string(pos, end_int));
            }
            catch (...) {
                ec = error_code::invalid_integer;
                if (error_pos)
                    *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            ret = lazy_entry(val);
            pos = end_int + 1;
            --item_limit;
        }
        else if (*pos == 'e') {
            // End of list or dictionary
            if (depth_stack.empty()) {
                ec = error_code::mismatched_end;
                if (error_pos)
                    *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            current_depth = depth_stack.top();
            depth_stack.pop();
            ++pos;
        }
        else if (*pos >= '0' && *pos <= '9') {
            // String
            const char* end_len = std::find(pos, end, ':');
            if (end_len == end) {
                ec = error_code::unexpected_eof;
                if (error_pos)
                    *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            std::string len_str(pos, end_len);
            size_t len = std::stoul(len_str);
            ++end_len;

            if (static_cast<size_t>(end - end_len) < len) {
                ec = error_code::invalid_string_length;
                if (error_pos)
                    *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            std::string str(end_len, end_len + len);
            ret = lazy_entry(str);
            pos = end_len + len;
            --item_limit;
        }
        else {
            ec = error_code::invalid_data_format;
            if (error_pos)
                *error_pos = static_cast<int>(pos - start);
            return 1;
        }
    }

    if (item_limit <= 0) {
        ec = error_code::item_limit_exceeded;
        if (error_pos)
            *error_pos = static_cast<int>(pos - start);
        return 1;
    }

    ec = error_code::no_error;
    return 0;
}

int decode_lazy_entry(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    // Assume the existence of 'lazy_entry', 'error_code', and any helper functions used are defined in 'file_context'.

    // Stack for managing nested structures
    std::vector<lazy_entry*> stack;
    stack.push_back(&ret);

    int depth = 0;
    int items = 0;
    const char* pos = start;

    while (pos < end && items < item_limit) {
        if (depth >= depth_limit) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos)
                *error_pos = pos - start;
            return 1;
        }

        // Skip whitespace
        while (pos < end && isspace(*pos))
            ++pos;

        if (pos >= end) {
            ec = error_code::unexpected_end_of_input;
            if (error_pos)
                *error_pos = pos - start;
            return 1;
        }

        switch (*pos) {
            case 'd': {
                // Dictionary start
                lazy_entry* dict = new lazy_entry(lazy_entry::dict_t);
                stack.back()->dict = dict;
                stack.push_back(dict);
                ++depth;
                ++pos;
                break;
            }
            case 'l': {
                // List start
                lazy_entry* list = new lazy_entry(lazy_entry::list_t);
                stack.back()->list = list;
                stack.push_back(list);
                ++depth;
                ++pos;
                break;
            }
            case 'i': {
                // Integer
                ++pos;
                const char* end_int = pos;
                while (end_int < end && isdigit(*end_int))
                    ++end_int;
                if (end_int == pos) {
                    ec = error_code::malformed_integer;
                    if (error_pos)
                        *error_pos = pos - start;
                    return 1;
                }
                stack.back()->integer = std::strtol(pos, const_cast<char**>(&end_int), 10);
                stack.back()->type = lazy_entry::integer_t;
                pos = end_int;
                ++items;
                break;
            }
            case 'e': {
                // End of dictionary or list
                if (stack.size() <= 1) {
                    ec = error_code::unexpected_end_marker;
                    if (error_pos)
                        *error_pos = pos - start;
                    return 1;
                }
                stack.pop_back();
                --depth;
                ++pos;
                break;
            }
            case 's': {
                // String
                if (pos + 1 >= end) {
                    ec = error_code::unexpected_end_of_input;
                    if (error_pos)
                        *error_pos = pos - start;
                    return 1;
                }
                const char* end_len = pos + 1;
                while (end_len < end && isdigit(*end_len))
                    ++end_len;
                if (end_len == pos + 1 || end_len >= end || *end_len != ':') {
                    ec = error_code::malformed_string;
                    if (error_pos)
                        *error_pos = pos - start;
                    return 1;
                }

                long len = std::strtol(pos + 1, const_cast<char**>(&end_len), 10);
                if (len < 0) {
                    ec = error_code::negative_string_length;
                    if (error_pos)
                        *error_pos = pos - start;
                    return 1;
                }

                if (end_len + len > end) {
                    ec = error_code::string_length_exceeds_input;
                    if (error_pos)
                        *error_pos = pos - start;
                    return 1;
                }

                stack.back()->string = std::string(end_len + 1, end_len + 1 + len);
                stack.back()->type = lazy_entry::string_t;
                pos = end_len + len;
                ++items;
                break;
            }
            default: {
                // Unknown or invalid character
                ec = error_code::invalid_data;
                if (error_pos)
                    *error_pos = pos - start;
                return 1;
            }
        }
    }

    if (pos != end) {
        ec = error_code::trailing_characters;
        if (error_pos)
            *error_pos = pos - start;
        return 1;
    }

    if (stack.size() != 1) {
        ec = error_code::unclosed_structure;
        if (error_pos)
            *error_pos = pos - start;
        return 1;
    }

    return 0;
}

int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::vector<int> stack;
    const char* pos = start;
    int depth = 0;
    int items_decoded = 0;

    while (pos < end && items_decoded < item_limit) {
        if (depth >= depth_limit) {
            ec = error_code::depth_exceeded;
            if (error_pos)
                *error_pos = static_cast<int>(pos - start);
            return 1;
        }

        switch (*pos) {
            case 'd':
                // Start of dictionary
                stack.push_back('d');
                depth++;
                pos++;
                break;

            case 'l':
                // Start of list
                stack.push_back('l');
                depth++;
                pos++;
                break;

            case 'i':
                // Integer
                pos++; // Skip 'i'
                const char* end_int = std::find(pos, end, 'e');
                if (end_int == end) {
                    ec = error_code::unexpected_end;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return 1;
                }
                try {
                    ret.type = lazy_entry::INTEGER;
                    ret.val.int_value = std::stoll(std::string(pos, end_int));
                } catch (...) {
                    ec = error_code::invalid_integer;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return 1;
                }
                pos = end_int + 1;
                items_decoded++;
                break;

            case 'e':
                // End of dictionary or list
                if (stack.empty()) {
                    ec = error_code::unexpected_end;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return 1;
                }
                char last = stack.back();
                stack.pop_back();
                if (last == 'd') {
                    // End of dictionary
                } else if (last == 'l') {
                    // End of list
                }
                pos++;
                depth--;
                break;

            case '4':
            case '3':
            case '2':
            case '1':
            case '0':
            case '9':
            case '8':
            case '7':
            case '6':
            case '5':
                // String
                {
                    const char* end_len = std::find(pos, end, ':');
                    if (end_len == end) {
                        ec = error_code::unexpected_end;
                        if (error_pos)
                            *error_pos = static_cast<int>(pos - start);
                        return 1;
                    }
                    try {
                        int len = std::stoi(std::string(pos, end_len));
                        if (pos + (end_len - pos) + 1 + len > end) {
                            ec = error_code::unexpected_end;
                            if (error_pos)
                                *error_pos = static_cast<int>(pos - start);
                            return 1;
                        }
                        ret.type = lazy_entry::STRING;
                        ret.val.string_value = std::string(end_len + 1, end_len + 1 + len);
                    } catch (...) {
                        ec = error_code::invalid_string;
                        if (error_pos)
                            *error_pos = static_cast<int>(pos - start);
                        return 1;
                    }
                    pos = end_len + 1 + len;
                    items_decoded++;
                }
                break;

            default:
                ec = error_code::invalid_token;
                if (error_pos)
                    *error_pos = static_cast<int>(pos - start);
                return 1;
        }
    }

    if (pos != end) {
        ec = error_code::trailing_data;
        if (error_pos)
            *error_pos = static_cast<int>(pos - start);
        return 1;
    }

    if (!stack.empty()) {
        ec = error_code::unexpected_end;
        if (error_pos)
            *error_pos = static_cast<int>(pos - start);
        return 1;
    }

    ret.type = lazy_entry::DICTIONARY;
    return 0;
}

int decode_lazy_entry(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> depth_stack;
    const char* pos = start;
    int depth = 0;
    int items = 0;

    while (pos < end && items < item_limit) {
        if (depth >= depth_limit) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos) *error_pos = static_cast<int>(pos - start);
            return 1;
        }

        if (*pos == 'd') {
            // Dictionary start
            depth++;
            ret.type = lazy_entry::dict_t;
            depth_stack.push(depth);
            pos++;
        } else if (*pos == 'l') {
            // List start
            depth++;
            ret.type = lazy_entry::list_t;
            depth_stack.push(depth);
            pos++;
        } else if (*pos == 'i') {
            // Integer
            ret.type = lazy_entry::integer_t;
            const char* int_end = std::find(pos + 1, end, 'e');
            if (int_end == end) {
                ec = error_code::unexpected_end_of_data;
                if (error_pos) *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            try {
                ret.string = std::string(pos + 1, int_end);
                ret.number = std::stoi(ret.string);
            } catch (...) {
                ec = error_code::invalid_integer;
                if (error_pos) *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            pos = int_end + 1;
            items++;
        } else if (*pos == 'e') {
            // End of current structure
            if (depth_stack.empty()) {
                ec = error_code::unexpected_end_marker;
                if (error_pos) *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            depth_stack.pop();
            pos++;
            depth--;
        } else if (isdigit(*pos) || *pos == ':') {
            // String
            const char* colon = std::find(pos, end, ':');
            if (colon == end) {
                ec = error_code::unexpected_end_of_data;
                if (error_pos) *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            int length;
            try {
                length = std::stoi(std::string(pos, colon));
            } catch (...) {
                ec = error_code::invalid_string_length;
                if (error_pos) *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            if (colon + 1 + length > end) {
                ec = error_code::unexpected_end_of_data;
                if (error_pos) *error_pos = static_cast<int>(pos - start);
                return 1;
            }

            ret.type = lazy_entry::string_t;
            ret.string.assign(colon + 1, length);
            pos = colon + 1 + length;
            items++;
        } else {
            ec = error_code::invalid_token;
            if (error_pos) *error_pos = static_cast<int>(pos - start);
            return 1;
        }
    }

    if (depth_stack.empty()) {
        ec = error_code::no_error;
        return 0;
    } else {
        ec = error_code::unclosed_structure;
        if (error_pos) *error_pos = static_cast<int>(pos - start);
        return 1;
    }
}

int decode_lazy_entry(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> depth_stack;
    std::stack<int> item_stack;
    char const* current = start;

    while (current < end) {
        if (depth_stack.size() >= static_cast<size_t>(depth_limit)) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos) *error_pos = static_cast<int>(current - start);
            return 1;
        }

        if (item_stack.size() >= static_cast<size_t>(item_limit)) {
            ec = error_code::item_limit_exceeded;
            if (error_pos) *error_pos = static_cast<int>(current - start);
            return 1;
        }

        switch (*current) {
            case 'd':
                depth_stack.push(depth_stack.size());
                current++;
                break;
            case 'l':
                item_stack.push(item_stack.size());
                current++;
                break;
            case 'i':
                // Parse integer
                try {
                    int64_t value = std::stoll(std::string(current + 1, end - current - 1));
                    ret.type = lazy_entry::t_integer;
                    ret.integer = value;
                    current += std::to_string(value).length() + 1; // +1 for 'i'
                } catch (...) {
                    ec = error_code::invalid_integer;
                    if (error_pos) *error_pos = static_cast<int>(current - start);
                    return 1;
                }
                break;
            case 'e':
                // End of dictionary or list
                if (depth_stack.size()) {
                    depth_stack.pop();
                } else if (item_stack.size()) {
                    item_stack.pop();
                }
                current++;
                break;
            case '0' ... '9':
                // Parse string
                try {
                    size_t len = std::stoll(std::string(current, end - current));
                    if (current + len + 1 > end) {
                        ec = error_code::unexpected_end;
                        if (error_pos) *error_pos = static_cast<int>(current - start);
                        return 1;
                    }
                    ret.type = lazy_entry::t_string;
                    ret.string = std::string(current + len + 1, len);
                    current += len + 1;
                } catch (...) {
                    ec = error_code::invalid_string;
                    if (error_pos) *error_pos = static_cast<int>(current - start);
                    return 1;
                }
                break;
            default:
                ec = error_code::invalid_input;
                if (error_pos) *error_pos = static_cast<int>(current - start);
                return 1;
        }
    }

    if (current != end) {
        ec = error_code::unexpected_end;
        if (error_pos) *error_pos = static_cast<int>(current - start);
        return 1;
    }

    return 0;
}
